using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using System.Xml.Linq;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public sealed class LayerDependencyTests
{
    private const string Prefix = "PaymentAuthorization";

    // Language core only: no I/O, network, persistence or framework namespaces.
    private static readonly HashSet<string> LanguageCore =
    [
        "System",
        "System.Collections.Generic",
        "System.Diagnostics.CodeAnalysis",
        "System.Runtime.CompilerServices",
        "System.Threading",
        "System.Threading.Tasks",
    ];

    private static readonly HashSet<string> ForbiddenCoreTypes =
    [
        "System.Console", "System.Environment", "System.AppContext", "System.Activator", "System.GC",
    ];

    private static readonly Dictionary<string, string[]> AllowedProjects = new()
    {
        ["Domain"] = [],
        ["Application"] = ["Domain"],
        ["Infrastructure"] = ["Domain", "Application"],
    };

    [Theory]
    [InlineData("Domain")]
    [InlineData("Application")]
    [InlineData("Infrastructure")]
    public void A_project_references_only_its_inner_neighbours_and_no_packages(string layer)
    {
        var csproj = Path.Combine(SolutionRoot(), "src", $"{Prefix}.{layer}", $"{Prefix}.{layer}.csproj");
        var doc = XDocument.Load(csproj);

        var projects = doc.Descendants("ProjectReference")
            .Select(e => Path.GetFileNameWithoutExtension((string)e.Attribute("Include")!))
            .ToList();
        var allowed = AllowedProjects[layer].Select(l => $"{Prefix}.{l}").ToHashSet();
        var violations = projects.Where(p => !allowed.Contains(p)).ToList();

        if (layer != "Infrastructure")
            violations.AddRange(doc.Descendants("PackageReference").Select(e => "package " + (string)e.Attribute("Include")!));

        Assert.True(violations.Count == 0, "Violations: " + string.Join(", ", violations));
    }

    [Theory]
    [InlineData(typeof(Money), new string[0])]
    [InlineData(typeof(AuthorizePayment), new[] { "Domain" })]
    public void Business_code_depends_only_on_itself_inner_layers_and_the_language_core(Type anchor, string[] innerLayers)
    {
        var ownLayer = anchor.Assembly.GetName().Name![(Prefix.Length + 1)..];
        var allowedPrefixes = innerLayers.Append(ownLayer).Select(l => $"{Prefix}.{l}").ToList();

        var violations = ReferencedTypes(anchor.Assembly)
            .Where(t => !IsAllowed(t.Namespace, t.Name, allowedPrefixes))
            .Select(t => $"{t.Namespace}.{t.Name}")
            .Distinct()
            .OrderBy(x => x)
            .ToList();

        Assert.True(violations.Count == 0, $"Violations in {ownLayer}: " + string.Join(", ", violations));
    }

    private static bool IsAllowed(string ns, string name, List<string> allowedPrefixes)
    {
        if (ForbiddenCoreTypes.Contains($"{ns}.{name}")) return false;
        if (LanguageCore.Contains(ns)) return true;
        return allowedPrefixes.Any(p => ns == p || ns.StartsWith(p + "."));
    }

    private static IEnumerable<(string Namespace, string Name)> ReferencedTypes(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();

        foreach (var handle in md.TypeReferences)
        {
            var r = md.GetTypeReference(handle);
            // Nested types report their declaring type's namespace through the resolution scope.
            if (r.ResolutionScope.Kind == HandleKind.TypeReference) continue;
            yield return (md.GetString(r.Namespace), md.GetString(r.Name));
        }
    }

    private static string SolutionRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !dir.GetFiles("*.slnx").Any()) dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("Solution root not found.");
    }
}
