            .Where(t => !IsAllowed(t.Namespace, t.Name, allowedPrefixes))
            .Select(t => $"{t.Namespace}.{t.Name}")
            .Distinct()
            .OrderBy(x => x)
            .ToList();

        Assert.True(violations.Count == 0, $"Violations in {ownLayer}: " + string.Join(", ", violations));
    }

    private static bool IsAllowed(string ns, string name, List<string> allowedPrefixes)
    {
        if (ForbiddenCoreTypes.Contains($"{ns}.{name}")) return false;
        if (LanguageCore.Contains(ns)) return true;
        return allowedPrefixes.Any(p => ns == p || ns.StartsWith(p + "."));
    }

    private static IEnumerable<(string Namespace, string Name)> ReferencedTypes(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();

        foreach (var handle in md.TypeReferences)
        {
            var r = md.GetTypeReference(handle);
            // Nested types report their declaring type's namespace through the resolution scope.
            if (r.ResolutionScope.Kind == HandleKind.TypeReference) continue;
            yield return (md.GetString(r.Namespace), md.GetString(r.Name));
        }
    }

    private static string SolutionRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !dir.GetFiles("*.slnx").Any()) dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("Solution root not found.");
    }
